/* Workspace interactions: office rooms, personal revisions and batch archives. */
function setupWorkbenchState(){state.managing??=false;state.selected??=new Set();state.rooms??=[];state.selectionParts??=[];}
function resourceKey(kind,id){return kind+'|'+id}
function chosenResources(){return [...state.selected].map(key=>{const i=key.indexOf('|');return {kind:key.slice(0,i),id:key.slice(i+1)}})}
async function renderLibrary(){setupWorkbenchState();const query=state.query,folder=state.folder,kind=state.libraryKind,filterKey=JSON.stringify([state.archiveFrom,state.archiveTo,state.archiveRegion]);const d=await api('/library?'+new URLSearchParams({date_from:state.archiveFrom||'',date_to:state.archiveTo||'',region:state.archiveRegion||'all'})+'&q='+encodeURIComponent(query)+'&kind='+kind+(folder?'&folder='+folder:''));if(filterKey!==JSON.stringify([state.archiveFrom,state.archiveTo,state.archiveRegion])||state.view!=='archive'||query!==state.query||folder!==state.folder||kind!==state.libraryKind)return;state.library=d;state.items=d.items;state.page=Math.min(state.page,Math.max(1,Math.ceil(d.items.length/12)));
 const current=d.folders.find(f=>f.id===folder),parent=d.folders.find(f=>f.id===current?.parent_id),folders=d.folders.filter(f=>(f.parent_id||null)===(folder||null));
 $('#content').innerHTML=heading('档案室',`<button class="btn ${state.managing?'selected':''}" data-work="manage-archive">${state.managing?'完成管理':'管理档案'}</button><button class="btn" data-action="new-folder">新建专题</button><button class="btn" data-action="organize">请${esc(name())}整理</button><button class="btn text" data-work="trash">回收站</button>`)+searchbar()+archiveFilters()+`<div class="folder-path"><button class="btn text" data-folder="">全部档案</button>${parent?`<span>/</span><button class="btn text" data-folder="${parent.id}">${esc(parent.name)}</button>`:''}${current?`<span>/</span><strong>${esc(current.name)}</strong>`:''}</div>`+(folders.length?`<div class="folder-grid">${folders.map(f=>`<div class="folder-tile"><button class="folder-card" data-folder="${f.id}"><span class="folder-icon">${uiIcon('folder')}</span><strong>${esc(f.name)}</strong><span>${f.count} 份</span></button><button class="icon-button folder-delete" data-work="delete-category" data-id="${f.id}" aria-label="删除专题${esc(f.name)}" title="删除专题">${uiIcon('trash')}</button></div>`).join('')}</div>`:'')+`<div class="filter-tabs">${Object.entries(kindNames).filter(([k])=>k!=='conversation').map(([k,v])=>`<button class="btn ${kind===k?'selected':''}" data-library-kind="${k}">${v}${k==='all'?'':` <small>${d.counts[k]||0}</small>`}</button>`).join('')}</div>`+(state.managing?`<div class="batch-bar"><label><input type="checkbox" id="select-page"> 选择本页</label><span id="selection-count">已选 ${state.selected.size} 份</span><button class="btn" data-work="batch-file">归入专题</button><button class="btn danger" data-work="batch-trash">批量删除</button><button class="btn" data-work="categories">管理档案类别</button><button class="btn text" data-action="export">导出档案</button></div>`:'')+(d.items.length?`<div class="resource-list">${d.items.slice((state.page-1)*12,state.page*12).map((r,i)=>{const k=resourceKey(r.resource_kind,r.resource_id);return `<div class="selectable-resource">${state.managing?`<label class="resource-select"><input type="checkbox" data-resource-key="${esc(k)}" aria-label="选择${esc(r.title)}" ${state.selected.has(k)?'checked':''}></label>`:''}${resourceCard(r,i+(state.page-1)*12)}</div>`}).join('')}</div>`+pagination(d.items.length):empty('暂无档案'));
}
async function openDocument(kind,id){const d=await api('/document?kind='+kind+'&id='+encodeURIComponent(id));state.document={kind,id,data:d};showDialog('#document-dialog',d.title,`<div class="doc-meta">${fmt(d.created)}${d.edited?' · 个人修订稿':d.mode?' · '+esc(d.mode):''}</div>${d.source_updated?'<div class="notice">原始记录有新增，你的修订稿已保留。</div>':''}<div class="formal">${md(d.content)}</div>${kind==='minutes'?`<details class="raw-record"><summary>完整讨论记录</summary><div class="formal">${md(d.raw_content)}</div></details>`:''}`,`<button class="btn" data-work="edit-document" data-kind="${kind}" data-id="${esc(id)}">编辑文件</button>${kind==='minutes'?`<button class="btn" data-minutes="${esc(id)}">请${esc(name())}更新纪要</button>`:''}`)}
async function editDocument(kind,id){const d=await api('/document?kind='+kind+'&id='+encodeURIComponent(id));state.editing={kind,id,revision:d.revision};showDialog('#document-dialog','编辑文件',`<form id="edit-document-form"><p class="edit-notice">保存为个人修订稿，原始来源与讨论记录保留。</p><div class="field"><label for="edit-title">标题</label><input id="edit-title" name="title" value="${esc(d.title)}" required maxlength="160"></div><div class="field"><label for="edit-content">正文</label><textarea id="edit-content" class="document-editor" name="content" required>${esc(d.content)}</textarea></div><details><summary>排版预览</summary><div id="edit-preview" class="formal">${md(d.content)}</div></details><div class="actions compose-actions"><button class="btn primary">保存修订</button><button type="button" class="btn" data-close="#document-dialog">取消</button></div></form>`)}
async function renderAssistant(){setupWorkbenchState();const rooms=await api('/conversations');if(state.view!=='assistant')return;state.rooms=rooms;if(!rooms.some(r=>r.id===state.scope))state.scope=rooms[0]?.id||'';const scope=state.scope,room=rooms.find(r=>r.id===scope),messages=scope?await api('/messages?scope='+encodeURIComponent(scope)):[];if(state.view!=='assistant'||state.scope!==scope)return;
 $('#content').innerHTML=heading('办公室',`<button class="btn" data-action="today-minutes">当日会议纪要</button><button class="btn text" data-work="room-trash">议事回收站</button>`)+`<p class="room-hint">可询问档案室材料与政研室笔记；秘书只提供检索和建议，原记录由你管理。</p><div class="office-workspace" style="--office-size:${Math.max(13,Math.min(19,Number(localStorage.getItem('yuewen-office-size')||15)))}px"><aside class="office-rooms"><button class="btn primary new-room" data-work="new-room">${uiIcon('plus')} 新建议事</button><div class="room-list">${rooms.map(r=>`<div class="room-row"><button class="room-item ${r.id===scope?'active':''}" data-work="select-room" data-id="${esc(r.id)}"><strong>${esc(r.title)}</strong><small>${fmt(r.updated)} · ${r.message_count} 条</small></button><div class="room-tools"><button class="btn text" data-work="rename-room" data-id="${esc(r.id)}" aria-label="重命名${esc(r.title)}">编辑</button><button class="btn text danger" data-work="delete-room" data-id="${esc(r.id)}" aria-label="删除${esc(r.title)}">删除</button></div></div>`).join('')}</div></aside><section class="office-conversation"><header class="room-heading"><h2>${esc(room?.title||'新议事')}</h2><div class="actions"><button class="btn text" data-work="message-trash">消息回收站</button><button class="btn text" data-work="office-font-smaller" aria-label="减小办公室字号">A−</button><button class="btn text" data-work="office-font-larger" aria-label="增大办公室字号">A＋</button></div></header><div id="chat-log" class="chat-log">${messages.length?messages.map(messageCard).join(''):empty('暂无议事记录')}</div><form id="chat-form" class="chat-compose"><label class="sr-only" for="office-question">向${esc(name())}提问</label><textarea id="office-question" name="question" required placeholder="与${esc(name())}议事">${esc(draft(scope||'new','question'))}</textarea><div class="actions compose-actions">${webToggle()}<span class="spacer"></span><button type="button" class="btn" data-voice="office-question">开始转写</button><button class="btn primary">发送</button></div><details><summary>附参考网页</summary><input class="search-input" type="url" name="url" data-web-url ${webEnabled()?'':'disabled'} placeholder="开启联网后可附参考网页" aria-label="参考网页地址"></details></form></section></div>`;
 const log=$('#chat-log');log.scrollTop=log.scrollHeight;
}
async function prepareQuestion(question,purpose){const room=await api('/conversations',{title:question.slice(0,45)});state.view='assistant';state.scope=room.id;state.special=null;state.purpose=purpose;saveDraft(room.id,'question',question);await render();$('#office-question').focus()}
async function categoryManager(){const d=await api('/library');state.library=d;showDialog('#organize-dialog','管理档案类别',`<div class="category-list">${d.folders.map(f=>`<div class="category-row"><span>${f.parent_id?esc(d.folders.find(p=>p.id===f.parent_id)?.name)+' / ':''}${esc(f.name)}</span><button class="btn text" data-work="rename-category" data-id="${f.id}">改名</button><button class="btn text danger" data-work="delete-category" data-id="${f.id}">删除</button></div>`).join('')}</div>`,`<button class="btn primary" data-action="new-folder">新建类别</button>`)}
async function workbenchAction(action,b){setupWorkbenchState();
 if(await attentionAction(action,b))return;
 if(action==='manage-archive'){state.managing=!state.managing;if(!state.managing)state.selected.clear();return renderLibrary()}
 if(action==='categories')return categoryManager();
 if(action==='rename-category'){const f=state.library.folders.find(x=>x.id===b.dataset.id),value=window.prompt('专题名称',f.name);if(value!==null){await api('/dossiers',{action:'rename',id:f.id,name:value});if($('#organize-dialog').open)await categoryManager();await renderLibrary()}return}
 if(action==='delete-category'){const f=state.library.folders.find(x=>x.id===b.dataset.id);if(await confirmAction('删除“'+f.name+'”？','删除此类别及其下级分类，文件保留在“全部档案”。')){await api('/dossiers',{action:'delete',id:f.id});if(state.folder===f.id||state.library.folders.some(x=>x.parent_id===f.id&&x.id===state.folder))state.folder=null;if($('#organize-dialog').open)await categoryManager();await renderLibrary()}return}
 if(action==='batch-file'){if(!state.selected.size)return toast('请先选择文件');showDialog('#organize-dialog','批量归入专题',`<form id="batch-file-form"><div class="field"><label for="batch-folder">将 ${state.selected.size} 份文件归入</label><select name="folder_id" id="batch-folder">${state.library.folders.map(f=>`<option value="${f.id}">${f.parent_id?esc(state.library.folders.find(p=>p.id===f.parent_id)?.name)+' / ':''}${esc(f.name)}</option>`).join('')}</select></div><button class="btn primary">确认归档</button></form>`);return}
 if(action==='batch-trash'){if(!state.selected.size)return toast('请先选择文件');if(await confirmAction('删除所选 '+state.selected.size+' 份文件？','文件移入回收站，原文、批注和修订稿可恢复。')){await api('/archive-batch',{action:'trash',items:chosenResources()});state.selected.clear();await renderLibrary();toast('已移入回收站')}return}
 if(action==='trash'){const rows=await api('/trash');showDialog('#organize-dialog','回收站',rows.length?rows.map(r=>`<div class="category-row"><span>${esc(r.title)}</span><button class="btn" data-work="restore-resource" data-kind="${r.kind}" data-id="${esc(r.id)}">恢复</button></div>`).join(''):empty('回收站为空'));return}
 if(action==='restore-resource'){await api('/archive-batch',{action:'restore',items:[{kind:b.dataset.kind,id:b.dataset.id}]});await workbenchAction('trash',b);await renderLibrary();return}
 if(action==='edit-document')return editDocument(b.dataset.kind,b.dataset.id);
 if(action==='new-room'){stopVoice();const r=await api('/conversations',{});state.scope=r.id;state.purpose='consultation';return renderAssistant()}
 if(action==='select-room'){stopVoice();state.scope=b.dataset.id;state.purpose='consultation';return renderAssistant()}
 if(action==='rename-room'){const r=state.rooms.find(r=>r.id===(b.dataset.id||state.scope));if(!r)return;const title=window.prompt('议题名称',r.title);if(title!==null){await api('/conversations',{action:'rename',id:r.id,title});await renderAssistant()}return}
 if(action==='delete-room'){const r=state.rooms.find(r=>r.id===b.dataset.id);if(r&&await confirmAction('将“'+r.title+'”移入回收站？','议事记录可恢复；相关日纪要将按现存议事重新整理。')){await api('/conversations',{action:'trash',id:r.id});await renderAssistant();toast('议事已移入回收站')}return}
 if(action==='room-trash'){const rooms=await api('/conversation-trash');showDialog('#organize-dialog','议事回收站',rooms.length?rooms.map(r=>`<div class="category-row"><span>${esc(r.title)} · ${r.message_count} 条</span><button class="btn" data-work="restore-room" data-id="${esc(r.id)}">恢复</button></div>`).join(''):empty('回收站为空'));return}
 if(action==='restore-room'){await api('/conversations',{action:'restore',id:b.dataset.id});await workbenchAction('room-trash',b);await renderAssistant();return}
 if(action==='office-font-smaller'||action==='office-font-larger'){const size=Math.max(13,Math.min(19,Number(localStorage.getItem('yuewen-office-size')||15)+(action==='office-font-larger'?1:-1)));localStorage.setItem('yuewen-office-size',size);$('.office-workspace').style.setProperty('--office-size',size+'px');return}
 if(action==='manage-notes'){state.managingNotes=!state.managingNotes;if(!state.managingNotes)state.selectedNoteArticles.clear();return renderRecords()}
 if(action==='batch-trash-notes'){if(!state.selectedNoteArticles.size)return toast('请先选择文章');if(await confirmAction('删除所选文章的全部批注？','该文章的全部批注、标记与心得将移入政研室回收站，原文保留。')){const all=await api('/search?mode=notes');const ids=all.filter(n=>state.selectedNoteArticles.has(n.article_id)).map(n=>n.id);if(ids.length)await api('/notes',{action:'trash',ids});state.selectedNoteArticles.clear();await renderRecords();toast('已移入回收站')}return}
 if(action==='clear-note-style'||action==='trash-note'){const id=b.dataset.id;if(action==='trash-note'&&!await confirmAction('删除这条批注？','批注可在政研室回收站恢复。'))return;await api('/notes',{action:action==='trash-note'?'trash':'clear-style',ids:[id]});if(state.article&&$('#reader').open)await refreshNotes(state.article.id);if(state.view==='notes')await renderRecords();toast(action==='trash-note'?'已移入回收站':'标记已取消');return}
 if(action==='notes-trash'){const rows=await api('/search?mode=notes-trash');showDialog('#organize-dialog','政研室回收站',rows.length?rows.map(n=>`<div class="category-row"><span>${esc(n.title)} · ${esc(n.text||n.quote).slice(0,80)}</span><button class="btn" data-work="restore-note" data-id="${esc(n.id)}">恢复</button></div>`).join(''):empty('回收站为空'));return}
 if(action==='restore-note'){await api('/notes',{action:'restore',ids:[b.dataset.id]});await workbenchAction('notes-trash',b);if(state.view==='notes')await renderRecords();return}
 if(action==='clear-selection-style'){if(!state.selectionParts?.length)return toast('请先选择原文中已标记的文字');const selected=JSON.stringify(state.selectionParts);const ids=state.article.notes.filter(n=>{if(n.style==='none')return false;try{return JSON.stringify(JSON.parse(n.anchors||'[]'))===selected}catch{return false}}).map(n=>n.id);if(!ids.length)return toast('没有找到与所选范围完全相同的标记，可在右侧逐条取消');await api('/notes',{action:'clear-style',ids});await refreshNotes(state.article.id);toast('所选标记已取消');return}
 if(action==='apply-style')return applySelectionStyle(b.dataset.style);
 if(action==='reader-full'){const r=$('#reader');r.classList.toggle('reader-full');syncReaderSelection();r.style.width='';r.style.height='';b.innerHTML=uiIcon('arrow_up_left_arrow_down_right')+(r.classList.contains('reader-full')?'还原大小':'专注全屏');return}
 if(action==='font-smaller'||action==='font-larger'){let size=Number(localStorage.getItem('yuewen-font')||17);size=Math.max(14,Math.min(28,size+(action==='font-larger'?1:-1)));localStorage.setItem('yuewen-font',size);document.documentElement.style.setProperty('--reading-size',size+'px');return}
 if(action==='runtime'){const r=await api('/runtime');showDialog('#document-dialog','原文与独立运行',`<div class="formal"><h3>一、原文阅读</h3><p>阅读页展示从来源网站提取的正文副本，可直接选文标注；“原始网页”打开发布网站。个人修订稿独立保存。</p><p>目前不在外部网页上直接画线。复杂页面的图片、表格仍应对照原站。</p><h3>二、每日采集</h3><p>由主一自带的后台程序完成：${esc(r.scheduler)}。${r.automatic?'自动采集已开启。':'自动采集当前关闭，可在设置中开启。'}</p><p>在项目文件夹双击“启动主一”，会独立启动后台并打开浏览器，不需要打开 Codex；关闭浏览器后后台仍运行。</p><p>电脑关机或睡眠期间无法采集，恢复运行后补收。要在电脑关闭时仍按时交付，需要另行部署常开服务器。</p></div>`);return}
}
async function workbenchSubmit(f){const values=Object.fromEntries(new FormData(f)),button=f.querySelector('button');button.disabled=true;try{if(f.id==='edit-document-form'){const editing={...state.editing};await api('/edit-document',{...editing,...values});toast('个人修订稿已保存');await openDocument(editing.kind,editing.id);if(state.view==='archive')await renderLibrary()}if(f.id==='batch-file-form'){await api('/archive-batch',{action:'file',items:chosenResources(),folder_id:values.folder_id});$('#organize-dialog').close();state.selected.clear();await renderLibrary();toast('已归入专题')}}catch(e){toast(e.message)}finally{button.disabled=false}}
let speechSession=null;
function stopVoice(){if(speechSession){speechSession.stopping=true;speechSession.recognition.stop();speechSession.status.textContent='正在结束转写…'}}
async function voice(target){const field=document.getElementById(target),button=$$('[data-voice]').find(b=>b.dataset.voice===target);if(speechSession?.target===target){stopVoice();return}if(speechSession)stopVoice();const SR=window.SpeechRecognition||window.webkitSpeechRecognition;if(!SR){toast('当前浏览器不支持语音转写，请使用系统听写（Mac 可按听写快捷键）。');return}const status=document.createElement('div');status.className='voice-status starting';status.setAttribute('role','status');status.setAttribute('aria-live','polite');status.innerHTML='<span class="voice-wave" aria-hidden="true"><i></i><i></i><i></i></span><span>正在启动转写…</span>';button.closest('form,section,.side-card')?.append(status);const sr=new SR(),session={recognition:sr,target,status,button,stopping:false};speechSession=session;button.textContent='停止转写';button.classList.add('recording');button.setAttribute('aria-pressed','true');
 sr.lang='zh-CN';sr.interimResults=true;sr.continuous=true;
 sr.onstart=()=>{if(speechSession!==session)return;status.classList.remove('starting');status.lastElementChild.textContent='正在转写，点击“停止转写”结束'};
 sr.onresult=e=>{if(!field.isConnected){sr.stop();return}let interim='';for(let i=e.resultIndex;i<e.results.length;i++){const t=e.results[i][0].transcript;if(e.results[i].isFinal){field.value+=(field.value&&!/[\s，。！？]$/.test(field.value)?' ':'')+t;field.dispatchEvent(new Event('input',{bubbles:true}))}else interim+=t}if(status.lastElementChild)status.lastElementChild.textContent=interim||'正在转写…'};
 sr.onerror=e=>{status.className='voice-status';status.textContent=({'not-allowed':'麦克风未获授权。','audio-capture':'没有检测到麦克风。','network':'语音服务连接失败，可使用系统听写。','no-speech':'未检测到语音。'})[e.error]||'转写未完成，请重试。'};
 sr.onend=()=>{if(speechSession===session)speechSession=null;button.textContent='开始转写';button.classList.remove('recording');button.setAttribute('aria-pressed','false');if(session.stopping||status.querySelector('.voice-wave')){status.className='voice-status';status.textContent='转写已结束，请核对文字后保存。'}};
 try{sr.start()}catch{speechSession=null;button.textContent='开始转写';button.classList.remove('recording');button.setAttribute('aria-pressed','false');status.className='voice-status';status.textContent='无法启动语音转写，可使用系统听写。'}
}
function captureSelection(){setupWorkbenchState();const s=window.getSelection(),box=$('#article-text');if(!s||s.isCollapsed||!box.contains(s.anchorNode)||!box.contains(s.focusNode))return;const range=s.getRangeAt(0),parts=[];for(const p of box.querySelectorAll('[data-paragraph]')){if(!range.intersectsNode(p))continue;const r=document.createRange();r.selectNodeContents(p);if(p.contains(range.startContainer))r.setStart(range.startContainer,range.startOffset);if(p.contains(range.endContainer))r.setEnd(range.endContainer,range.endOffset);const raw=r.toString(),quote=raw.trim();if(!quote)continue;const prefix=document.createRange();prefix.selectNodeContents(p);prefix.setEnd(r.startContainer,r.startOffset);const start=prefix.toString().length+raw.length-raw.trimStart().length,index=Number(p.dataset.paragraph),original=state.article.body.split('\n\n')[index],shown=p.textContent;const leading=original.indexOf(shown);const actual=(leading>=0?leading:0)+start;if(original.slice(actual,actual+quote.length)!==quote)continue;parts.push({paragraph:index,quote,anchor_start:[...original.slice(0,actual)].length,anchor_end:[...original.slice(0,actual+quote.length)].length})}if(!parts.length)return;state.selectionParts=parts;state.quote=parts.map(p=>p.quote).join('\n\n');state.paragraph=parts.length===1?parts[0].paragraph:-1;state.anchorStart=parts.length===1?parts[0].anchor_start:null;state.anchorEnd=parts.length===1?parts[0].anchor_end:null;$('#selected-quote').innerHTML=`<div class="selected-quote">${esc(state.quote)}</div><div class="selection-status">已选 ${[...state.quote].length} 字 · 点按下方工具即可标记</div><button type="button" class="btn text" data-action="clear-quote">取消选文</button>`;$$('[data-work="apply-style"]').forEach(b=>b.disabled=false);toggleInspector(true)}
async function applySelectionStyle(style){if(!state.selectionParts?.length)return toast('请先在左侧原文中选取文字');const id=state.article.id,color=$('#note-form input[name="color"]:checked')?.value||'red';await api('/note',{article_id:id,quote:state.quote,anchors:state.selectionParts,style,color,kind:$('#note-form select[name="kind"]').value,text:''});await refreshNotes(id);toast(({highlight:'高亮',underline:'下划线',strike:'删除线'})[style]+'已保存；再点一下标记可删除此处全部标记')}
function highlight(text,notes,index){const chars=[...text],spans=[];for(const n of [...notes].reverse()){if(n.style==='none')continue;let anchors=[];try{anchors=JSON.parse(n.anchors||'[]')}catch{}if(!anchors.length)anchors=[{paragraph:n.paragraph,quote:n.quote,anchor_start:n.anchor_start,anchor_end:n.anchor_end}];for(const a of anchors){if(!a.quote||(a.paragraph>=0&&a.paragraph!==index))continue;let start=a.anchor_start??[...text.slice(0,Math.max(0,text.indexOf(a.quote)))].length,end=a.anchor_end??start+[...a.quote].length;if(chars.slice(start,end).join('')!==a.quote)continue;spans.push({id:n.id,start,end,style:n.style||'highlight',color:n.color||'red'})}}const edges=[...new Set([0,chars.length,...spans.flatMap(s=>[s.start,s.end])])].sort((a,b)=>a-b);return edges.slice(0,-1).map((start,i)=>{const end=edges[i+1],active=spans.filter(s=>s.start<=start&&s.end>=end),classes=[];for(const style of ['highlight','underline','strike']){const n=active.filter(s=>s.style===style).at(-1);if(n)classes.push('annot-'+style,style+'-'+n.color)}const value=esc(chars.slice(start,end).join(''));return classes.length?`<span class="${esc(classes.join(' '))}" data-mark-ids="${esc([...new Set(active.map(n=>n.id))].join(','))}" role="button" tabindex="0" title="点击取消此处标记，文字批注保留" aria-label="取消此处标记">${value}</span>`:value}).join('')}
function wireReaderSizing(){const reader=$('#reader'),grip=$('#reader-grip'),splitter=$('#reader-splitter');document.documentElement.style.setProperty('--reading-size',Number(localStorage.getItem('yuewen-font')||17)+'px');if(grip)grip.addEventListener('pointerdown',e=>{e.preventDefault();grip.setPointerCapture(e.pointerId);const rect=reader.getBoundingClientRect(),x=e.clientX,y=e.clientY;const move=ev=>{reader.classList.remove('reader-full');$('#reader [data-work="reader-full"]').textContent='最大化';reader.style.width=Math.min(innerWidth-24,Math.max(Math.min(720,innerWidth-24),rect.width+2*(ev.clientX-x)))+'px';reader.style.height=Math.min(innerHeight-24,Math.max(400,rect.height+2*(ev.clientY-y)))+'px'};const end=()=>{grip.removeEventListener('pointermove',move);grip.removeEventListener('pointerup',end);grip.removeEventListener('pointercancel',end)};grip.addEventListener('pointermove',move);grip.addEventListener('pointerup',end);grip.addEventListener('pointercancel',end)});
 if(splitter){splitter.addEventListener('pointerdown',e=>{e.preventDefault();splitter.setPointerCapture(e.pointerId);const move=ev=>{const right=reader.getBoundingClientRect().right;$('.reader-columns').style.setProperty('--aside-width',Math.min(reader.clientWidth*.55,Math.max(260,right-ev.clientX))+'px')};const end=()=>{splitter.removeEventListener('pointermove',move);splitter.removeEventListener('pointerup',end);splitter.removeEventListener('pointercancel',end)};splitter.addEventListener('pointermove',move);splitter.addEventListener('pointerup',end);splitter.addEventListener('pointercancel',end)});splitter.addEventListener('keydown',e=>{if(!['ArrowLeft','ArrowRight'].includes(e.key))return;e.preventDefault();const w=$('.reader-aside').clientWidth;$('.reader-columns').style.setProperty('--aside-width',Math.min(reader.clientWidth*.55,Math.max(260,w+(e.key==='ArrowLeft'?20:-20)))+'px')})}}
document.addEventListener('change',e=>{setupWorkbenchState();if(e.target.dataset.resourceKey){e.target.checked?state.selected.add(e.target.dataset.resourceKey):state.selected.delete(e.target.dataset.resourceKey)}if(e.target.id==='select-page'){for(const b of $$('[data-resource-key]')){b.checked=e.target.checked;b.checked?state.selected.add(b.dataset.resourceKey):state.selected.delete(b.dataset.resourceKey)}}if($('#selection-count'))$('#selection-count').textContent='已选 '+state.selected.size+' 份';if(e.target.dataset.noteArticle){e.target.checked?state.selectedNoteArticles.add(e.target.dataset.noteArticle):state.selectedNoteArticles.delete(e.target.dataset.noteArticle)}if(e.target.id==='select-research-page'){for(const b of $$('[data-note-article]')){b.checked=e.target.checked;b.checked?state.selectedNoteArticles.add(b.dataset.noteArticle):state.selectedNoteArticles.delete(b.dataset.noteArticle)}}if($('#research-selection-count'))$('#research-selection-count').textContent='已选 '+state.selectedNoteArticles.size+' 篇'});
document.addEventListener('input',e=>{if(e.target.id==='edit-content'&&$('#edit-preview'))$('#edit-preview').innerHTML=md(e.target.value)});
